{{-- Formulaire indépendant pour enregistrer un nouveau mot de passe avec le jeton reçu. --}}
<!doctype html>
<html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="csrf-token" content="{{ csrf_token() }}"><title>Nouveau mot de passe · IT-Docs</title><link rel="stylesheet" href="{{ asset('css/app.css') }}?v=20260926-2"></head>
<body class="reset-page"><main class="reset-card"><img src="{{ asset('assets/logo-it-docs-blue.png') }}" alt="IT-Docs"><h1>Créer un nouveau mot de passe</h1><p>Choisissez un nouveau mot de passe sécurisé pour votre compte.</p><form id="resetForm"><input type="hidden" name="token" value="{{ $token }}"><label>Adresse e-mail</label><input name="email" type="email" value="{{ $email }}" required><label>Nouveau mot de passe</label><div class="password-field"><input id="newPassword" name="password" type="password" minlength="8" required><button type="button" class="password-toggle" onclick="togglePassword('newPassword',this)">Afficher</button></div><label>Confirmer le mot de passe</label><div class="password-field"><input id="confirmPassword" name="password_confirmation" type="password" minlength="8" required><button type="button" class="password-toggle" onclick="togglePassword('confirmPassword',this)">Afficher</button></div><button class="primary full" type="submit">Enregistrer le nouveau mot de passe</button><div id="resetMessage" role="status"></div><a id="backToLogin" class="reset-link" href="{{ route('login') }}" hidden>Retourner à la fenêtre de connexion</a></form></main><script>
const token=document.querySelector('meta[name="csrf-token"]').content;
function togglePassword(id,b){const e=document.getElementById(id);e.type=e.type==='password'?'text':'password';b.textContent=e.type==='password'?'Afficher':'Masquer'}
document.getElementById('resetForm').addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.target);const button=e.target.querySelector('[type="submit"]');button.disabled=true;try{const r=await fetch('/reset-password',{method:'POST',headers:{'Accept':'application/json','X-CSRF-TOKEN':token},body:f});const j=await r.json();if(!r.ok)throw Error(j.message||Object.values(j.errors||{}).flat().join(' '));document.getElementById('resetMessage').textContent=j.message;document.getElementById('backToLogin').hidden=false}catch(err){document.getElementById('resetMessage').textContent=err.message;button.disabled=false}});
</script></body></html>
